===== RegistrationDates =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Shared rules for an owner's registration date. The <em>effective</em> registration date is the one
 * supplied in the request, or the server's current date when none was supplied; it must always fall on
 * a business day, so a Saturday or Sunday is rolled forward to the next Monday. Every value derived from
 * the registration date (the stored {@code registrationDate}, the membership number's year segment and
 * the per-day create-limit bucket) is computed from this adjusted date.
 *
 * <p>The per-day owner-count policy also lives here: {@link #DAILY_LIMIT} is the hard cap enforced at
 * create time, and {@link #BULK_WARNING_THRESHOLD} is the (lower) count above which a response carries
 * a bulk-signup warning. Both tiers are counted against {@link #countOn(LocalDate, OwnerRepository)}.
 */
final class RegistrationDates {

    /** Maximum number of owners that may be created for a single day. */
    static final int DAILY_LIMIT = 100;

    /** Owners created for a single day beyond which a response carries a bulk-signup warning. */
    static final int BULK_WARNING_THRESHOLD = 80;

    private RegistrationDates() {
    }

    /** Count the owners whose stored registration date equals {@code businessDay}. */
    static int countOn(LocalDate businessDay, OwnerRepository repository) {
        int count = 0;
        for (Owner existing : repository.findAll()) {
            if (businessDay != null && businessDay.equals(existing.getRegistrationDate())) {
                count++;
            }
        }
        return count;
    }

    /**
     * The effective, business-day registration date: {@code supplied} when non-null, otherwise the
     * server's current date, rolled forward to the next Monday when it lands on a weekend.
     */
    static LocalDate effective(LocalDate supplied) {
        return toBusinessDay(supplied != null ? supplied : LocalDate.now());
    }

    /** Roll a weekend date forward to the next Monday; a weekday is returned unchanged. */
    static LocalDate toBusinessDay(LocalDate date) {
        if (date.getDayOfWeek() == DayOfWeek.SATURDAY) {
            return date.plusDays(2);
        }
        if (date.getDayOfWeek() == DayOfWeek.SUNDAY) {
            return date.plusDays(1);
        }
        return date;
    }
}
===== ValidateOwnerPostcode =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

/**
 * Validates an owner's postcode when one is supplied, so an unacceptable value is a 400 before the
 * owner is ever persisted. Runs after the body has been bound and published (by {@link ValidateNewOwner}
 * on create / {@link ValidateOwner} on update) and before the owner is built or loaded.
 *
 * <p>Postcode is optional: a {@code null} or blank value is left untouched and accepted. When present it
 * must be exactly four digits; otherwise it is rejected. The city's region is derived through the single
 * {@link Owner#regionOf(String) city-to-region table}, and when the region is known the postcode must
 * fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
 * no known region accepts any four-digit postcode.
 */
public class ValidateOwnerPostcode {

    /** A postcode is exactly four digits. */
    private static final Pattern POSTCODE = Pattern.compile("^[0-9]{4}$");

    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
        String postcode = request.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return; // optional when absent — request contract stays backward-compatible
        }
        if (!POSTCODE.matcher(postcode).matches()) {
            throw new InvalidPostcodeException(postcode, "must be four digits");
        }
        int[] range = Owner.postcodeRangeOf(Owner.regionOf(request.getCity()));
        if (range != null) {
            int value = Integer.parseInt(postcode);
            if (value < range[0] || value > range[1]) {
                throw new InvalidPostcodeException(postcode,
                        "out of range " + range[0] + "-" + range[1] + " for city '" + request.getCity() + "'");
            }
        }
    }
}
===== Household =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * Single source of truth for household identity. A household groups owners that share the same last
 * name and the same address, compared case-insensitively with surrounding and internal whitespace
 * collapsed (so "Smith" / " smith " and "10  Main St" / "10 Main St" belong together).
 *
 * <p>The {@link #id(String, String)} derived from that normalized pair is stable: the same last name
 * and address always map to the same value, so every member of a household — including one that joins
 * via {@code sharesHousehold} — receives an identical {@code householdId}.
 */
final class Household {

    private Household() {
    }

    /** Lower-case (locale-independent) with leading/trailing and repeated internal whitespace collapsed. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /**
     * The canonical household key for a (lastName, address) pair — the single definition of household
     * membership. Two owners belong to the same household exactly when their keys are equal; {@link #id}
     * hashes this same key, so the duplicate check and the assigned id can never diverge.
     *
     * <p>Addresses are compared in their {@link OwnerAddress normalized} form (whitespace collapsed,
     * upper-cased, abbreviations expanded) so that equivalent spellings — "12 main st" and
     * "12 MAIN STREET" — belong to the same household even when stored data was not normalized.
     */
    static String key(String lastName, String address) {
        return normalize(lastName) + "\n" + OwnerAddress.normalize(address);
    }

    /**
     * Stable household identifier for the given last name and address: {@code "H-"} followed by the
     * first 12 hex characters of the SHA-256 of the {@link #key household key}.
     */
    static String id(String lastName, String address) {
        String key = key(lastName, address);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder("H-");
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }
}
===== BuildOwner =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        // The effective registration date (supplied in the request, or the server date when omitted)
        // must fall on a business day: a weekend date rolls forward to the next Monday. Every value
        // derived from it (membership number year, daily-limit bucket) then uses this adjusted date.
        owner.setRegistrationDate(RegistrationDates.effective(owner.getRegistrationDate()));
        built.set(owner);
    }
}

