package org.springframework.samples.petclinic.model;

import org.springframework.core.style.ToStringCreator;

import jakarta.persistence.*;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Pattern;

import java.time.LocalDate;
import java.util.*;

/**
 * Simple JavaBean domain object representing an owner.
 *
 * @author Ken Krebs
 * @author Juergen Hoeller
 * @author Sam Brannen
 * @author Michael Isvy
 */
@Entity
@Table(name = "owners")
public class Owner extends Person {
    @Column(name = "address")
    @NotEmpty
    private String address;

    @Column(name = "city")
    @NotEmpty
    private String city;

    @Column(name = "postcode")
    private String postcode;

    @Column(name = "telephone")
    @NotEmpty
    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ then 8 to 15 digits)")
    private String telephone;

    @Column(name = "email")
    private String email;

    @Column(name = "registration_date")
    private LocalDate registrationDate;

    @Column(name = "customer_code")
    private String customerCode;

    @Column(name = "membership_number")
    private String membershipNumber;

    @Column(name = "household_id")
    private String householdId;

    @Column(name = "namesake_count")
    private Integer namesakeCount;

    @Transient
    private Boolean bulkSignupWarning;

    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
    private Set<Pet> pets;

    public String getAddress() {
        return this.address;
    }

    public void setAddress(String address) {
        this.address = address;
    }

    public String getCity() {
        return this.city;
    }

    public void setCity(String city) {
        this.city = city;
    }

    public String getPostcode() {
        return this.postcode;
    }

    public void setPostcode(String postcode) {
        this.postcode = postcode;
    }

    public String getTelephone() {
        return this.telephone;
    }

    public void setTelephone(String telephone) {
        this.telephone = telephone;
    }

    public String getEmail() {
        return this.email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public LocalDate getRegistrationDate() {
        return this.registrationDate;
    }

    public void setRegistrationDate(LocalDate registrationDate) {
        this.registrationDate = registrationDate;
    }

    public String getCustomerCode() {
        return this.customerCode;
    }

    public void setCustomerCode(String customerCode) {
        this.customerCode = customerCode;
    }

    public String getMembershipNumber() {
        return this.membershipNumber;
    }

    public void setMembershipNumber(String membershipNumber) {
        this.membershipNumber = membershipNumber;
    }

    public String getHouseholdId() {
        return this.householdId;
    }

    public void setHouseholdId(String householdId) {
        this.householdId = householdId;
    }

    public Integer getNamesakeCount() {
        return this.namesakeCount;
    }

    public void setNamesakeCount(Integer namesakeCount) {
        this.namesakeCount = namesakeCount;
    }

    /**
     * Whether this response should carry a bulk-signup warning: {@code true} when more than 80 owners
     * have already been created for this owner's registration day. Computed per request, not persisted.
     */
    public Boolean getBulkSignupWarning() {
        return this.bulkSignupWarning;
    }

    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
        this.bulkSignupWarning = bulkSignupWarning;
    }

    /**
     * The owner's membership level, a number from 1 to 3 fixed at creation. Starts at 1; add 1 when an
     * email is present; add 1 when {@code namesakeCount} is 0; capped at 3. Level 4 is reserved for
     * tenure and is never produced here.
     */
    public int getMembershipLevel() {
        int level = 1;
        boolean hasEmail = this.email != null && !this.email.isBlank();
        if (hasEmail) {
            level++;
        }
        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
        if (unique) {
            level++;
        }
        return Math.min(level, 3);
    }

    /**
     * Fixed city-to-region table mapping each known city to its canonical region string.
     */
    private static final Map<String, String> CITY_REGION = Map.of(
        "Sydney", "NSW",
        "Melbourne", "VIC",
        "Brisbane", "QLD");

    /**
     * Region -> inclusive {low, high} four-digit postcode range: the single canonical home of the
     * postcode bands (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), read via
     * {@link #postcodeRangeOf(String)} by both locality derivation and the create-time range check.
     */
    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
        "NSW", new int[] {2000, 2099},
        "VIC", new int[] {3000, 3099},
        "QLD", new int[] {4000, 4099});

    /**
     * The canonical region for {@code city} derived from the fixed city-to-region table
     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the
     * city is not in the table. The single source of truth for both the city fallback of
     * {@link #getLocality() locality} and the create-time postcode range check.
     */
    public static String regionOf(String city) {
        return CITY_REGION.getOrDefault(city, "UNKNOWN");
    }

    /**
     * The inclusive {low, high} four-digit postcode band for {@code region} (NSW 2000-2099,
     * VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no band. This is the single
     * source of truth for the bands, shared by {@link #regionOfPostcode(String) locality derivation} and
     * the create-time postcode range check.
     */
    public static int[] postcodeRangeOf(String region) {
        return REGION_POSTCODES.get(region);
    }

    /**
     * The canonical region whose postcode band contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
     * QLD 4000-4099), or {@code null} when {@code postcode} is absent, not four digits, or in no known
     * range.
     */
    public static String regionOfPostcode(String postcode) {
        if (postcode == null || !postcode.matches("[0-9]{4}")) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * The owner's locality: the canonical region derived by preferring the {@link #getPostcode() postcode}
     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only when the postcode is absent or in no
     * known range falling back to the {@link #getCity() city}-to-region table
     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}). {@code "UNKNOWN"} when neither
     * resolves. Preferring the postcode disambiguates cities that share a name while still returning the
     * same region for known cities.
     */
    public String getLocality() {
        String byPostcode = regionOfPostcode(this.postcode);
        return byPostcode != null ? byPostcode : regionOf(this.city);
    }

    /**
     * The single Luhn check digit (0-9) computed over the digits contained in the
     * {@link #getCustomerCode() customerCode}: non-digit characters are ignored, each second digit from
     * the right is doubled (subtracting 9 when the double exceeds 9), the results are summed, and the
     * check digit is {@code (10 - sum % 10) % 10}. {@code 0} when no customer code is assigned.
     */
    public int getCheckDigit() {
        String code = this.customerCode;
        if (code == null) {
            return 0;
        }
        int sum = 0;
        boolean dbl = true;
        for (int i = code.length() - 1; i >= 0; i--) {
            char c = code.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    /**
     * The owner's preferred contact channel: {@code "EMAIL"} when an email is present, otherwise
     * {@code "PHONE"}.
     */
    public String getContactPreference() {
        boolean hasEmail = this.email != null && !this.email.isBlank();
        return hasEmail ? "EMAIL" : "PHONE";
    }

    /**
     * The single canonical format of an owner's identity key — the one value all duplicate detection is
     * expressed through: {@code telephone + "|" + (email or empty) + "|" + (householdId or empty)}. The
     * telephone and household id are used as given (they are expected to already be canonical: E.164 and
     * an assigned household id); the email is lower-cased here and a null/blank email, telephone or
     * household id contributes an empty component. This is the only place the {@code "|"}-join lives;
     * every producer of the key (the stored-owner {@link #getIdentityKey()} and the create-time check in
     * {@code OwnerIdentity}) routes through here so the formats cannot drift.
     */
    public static String identityKey(String telephone, String email, String householdId) {
        String tel = (telephone == null) ? "" : telephone;
        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
        String household = (householdId == null || householdId.isBlank()) ? "" : householdId;
        return tel + "|" + mail + "|" + household;
    }

    /**
     * The owner's derived identity key, built from its stored canonical telephone (E.164), email and
     * household id via {@link #identityKey(String, String, String)}. Two owners are duplicates exactly
     * when their whole identity keys are equal.
     */
    public String getIdentityKey() {
        return identityKey(this.telephone, this.email, this.householdId);
    }

    protected Set<Pet> getPetsInternal() {
        if (this.pets == null) {
            this.pets = new HashSet<>();
        }
        return this.pets;
    }

    protected void setPetsInternal(Set<Pet> pets) {
        this.pets = pets;
    }

    public List<Pet> getPets() {
        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
        return Collections.unmodifiableList(sortedPets);
    }

    public void setPets(List<Pet> pets) {
        this.pets = new HashSet<>(pets);
    }

    public void addPet(Pet pet) {
        getPetsInternal().add(pet);
        pet.setOwner(this);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name) {
        return getPet(name, false);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name, boolean ignoreNew) {
        name = name.toLowerCase();
        for (Pet pet : getPetsInternal()) {
            if (!ignoreNew || !pet.isNew()) {
                String compName = pet.getName();
                compName = compName.toLowerCase();
                if (compName.equals(name)) {
                    return pet;
                }
            }
        }
        return null;
    }

    public Pet getPet(Integer petId) {
        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
    }

    @Override
    public String toString() {
        return new ToStringCreator(this)

            .append("id", this.getId())
            .append("new", this.isNew())
            .append("lastName", this.getLastName())
            .append("firstName", this.getFirstName())
            .append("address", this.address)
            .append("city", this.city)
            .append("telephone", this.telephone)
            .toString();
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the {@code membershipNumber} formatted {@code <customerCode>-M<YY>}, where
 * {@code <customerCode>} is the owner's customer code and YY is the last two digits of the
 * registrationDate year (e.g. {@code SYD-SMI-0007-M26}). Runs after {@link AssignCustomerCode} so the
 * customer code is already assigned, and after {@link BuildOwner} which defaults the registration date.
 */
public class AssignMembershipNumber {

    public void service(@Val Owner owner) {
        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
        owner.setMembershipNumber(String.format("%s-M%s", owner.getCustomerCode(), yy));
    }
}

